/**
 * Fast search helper for matching query against code, city, name, state, or country.
 */
export function searchAirports(query: string, limit: number = 8): Airport[] {
  if (!query) return [];
  const q = query.trim().toLowerCase();
  if (!q) return [];

  const exactCode: Airport[] = [];
  const startsWithCode: Airport[] = [];
  const startsWithCity: Airport[] = [];
  const containsCityOrState: Airport[] = [];
  const containsName: Airport[] = [];

  for (let i = 0; i < AIRPORTS.length; i++) {
    const a = AIRPORTS[i];
    const codeLower = a.code.toLowerCase();
    const cityLower = a.city ? a.city.toLowerCase() : '';
    const nameLower = a.name ? a.name.toLowerCase() : '';
    const stateLower = a.state ? a.state.toLowerCase() : '';
    const stateFullLower = a.state_full ? a.state_full.toLowerCase() : '';

    if (codeLower === q) {
      exactCode.push(a);
    } else if (codeLower.startsWith(q)) {
      startsWithCode.push(a);
    } else if (cityLower.startsWith(q)) {
      startsWithCity.push(a);
    } else if (cityLower.includes(q) || stateLower === q || stateFullLower.startsWith(q) || stateFullLower === q) {
      containsCityOrState.push(a);
    } else if (nameLower.includes(q)) {
      containsName.push(a);
    }

    if (exactCode.length + startsWithCode.length + startsWithCity.length + containsCityOrState.length >= limit * 3) {
      break;
    }
  }

  const combined = [...exactCode, ...startsWithCode, ...startsWithCity, ...containsCityOrState, ...containsName];
  const seen = new Set<string>();
  const results: Airport[] = [];
  for (let j = 0; j < combined.length; j++) {
    const item = combined[j];
    if (!seen.has(item.code)) {
      seen.add(item.code);
      results.push(item);
      if (results.length >= limit) break;
    }
  }
  return results;
}

export function getAirportByCode(code: string): Airport | null {
  if (!code) return null;
  const clean = code.trim().toUpperCase();
  for (let i = 0; i < AIRPORTS.length; i++) {
    if (AIRPORTS[i].code === clean) return AIRPORTS[i];
  }
  return null;
}
